create or replace function public.admin_get_operations_dashboard() returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid();
begin
 if not (private.admin_is_owner(uid) or private.admin_can('analytics.view',uid) or private.admin_can('finance.billing',uid) or private.admin_can('content.manage',uid) or private.admin_can('hotseat.manage',uid)) then raise exception 'Admin dashboard permission required'; end if;
 return jsonb_build_object('store',case when private.admin_is_owner(uid) or private.admin_can('finance.billing',uid) then coalesce((select jsonb_agg(to_jsonb(s) order by s.price_ngn,s.name) from public.store_catalog s),'[]'::jsonb) else '[]'::jsonb end,'sweepstakes',case when private.admin_is_owner(uid) or private.admin_can('activities.manage',uid) then coalesce((select jsonb_agg(to_jsonb(s) order by s.updated_at desc) from public.sweepstakes_config s),'[]'::jsonb) else '[]'::jsonb end,'finance',case when private.admin_is_owner(uid) or private.admin_can('analytics.view',uid) or private.admin_can('finance.billing',uid) then jsonb_build_object('successful',coalesce((select count(*) from public.payment_transactions where status='success'),0),'pending',coalesce((select count(*) from public.payment_transactions where status='pending'),0),'failed',coalesce((select count(*) from public.payment_transactions where status='failed'),0),'gross_minor',coalesce((select sum(amount) from public.payment_transactions where status='success'),0)) else '{}'::jsonb end,'content',case when private.admin_is_owner(uid) or private.admin_can('content.manage',uid) then jsonb_build_object('confessions_pending',coalesce((select count(*) from public.confessions where not is_published),0),'confessions_published',coalesce((select count(*) from public.confessions where is_published),0),'events',coalesce((select count(*) from public.events),0),'groups',coalesce((select count(*) from public.groups),0)) else '{}'::jsonb end,'hotseat',case when private.admin_is_owner(uid) or private.admin_can('hotseat.manage',uid) then jsonb_build_object('scheduled_streams',coalesce((select count(*) from public.live_streams where status in ('scheduled','live')),0),'hosts',coalesce((select count(*) from public.hot_seat_hosts),0),'break_content',coalesce((select count(*) from public.hot_seat_break_content where enabled),0),'polls',coalesce((select count(*) from public.hot_seat_break_polls where enabled),0)) else '{}'::jsonb end,'hotseat_presence',case when private.admin_is_owner(uid) or private.admin_can('hotseat.manage',uid) then coalesce((select to_jsonb(h) from public.hot_seat_presence_settings h where h.id=true limit 1),jsonb_build_object('enabled',false,'title','Hot Seat','message','Hot Seat is live.')) else '{}'::jsonb end);
end $$;